    text: """بِسْمِ اللهِ الرَّحْمَنِ الرَّحِيمِ

قاعدة جليلة

إذا أردت الانتفاع بالقرآن فاجمع قلبك عند تلاوته وسماعه، وأَلْقِ
سَمْعَك، وأحضر حضورَ من يخاطبه به من تكلّم به سبحانه منه إليه؛ فإنّه
خطابٌ منه لك على لسان رسوله.

قال تعالى: ﴿إِنَّ فِي ذَٰلِكَ لَذِكْرَىٰ لِمَنْ كَانَ لَهُ قَلْبٌ أَوْ أَلْقَى
السَّمْعَ وَهُوَ شَهِيدٌ﴾ [ق/ ٣٧].

وذلك أن تمام التأثير لما كان موقوفًا على مُؤَثِّر مقتضٍ، ومحلّ
قابل، وشرطٍ لحصول الأثر، وانتفاء المانع الذي يمنع منه؛ تضمنت
