        """وقد جمعت هذه السورة من أصول الإيمان ما يكفي ويشفي ويغني عن كلام أهل الكلام ومعقول أهل المعقول؛ فإنها تضمنت تقرير المبدأ والمعاد والتوحيد والنبوة والإيمان بالملائكة، وانقسام الناس إلى هالك شقي وفائز سعيد، وأوصاف هؤلاء وهؤلاء، وتضمنت إثبات صفات الكمال لله وتنزيهه عما يضاد كماله من النقائص والعيوب، وذكر فيها العالمين: الصغرى والكبرى، فالأكبر - وهو عالم الآخرة - والأصغر - وهو عالم الدنيا - وذكر فيها خلق الإنسان ونشأته وإعادته، وحاله عند وفاته ويوم معاده، وإحاطة سبحانه به من كل وجه، حتى علمه بوساوس نفسه، وإقامة الحفظة عليه يحصون عليه كل لفظ يتكلم بها، وأنه يوافيه يوم القيامة ومعه سائق يسوقه إليه وشاهد يشهد عليه، فإذا أحضره السائق، قال: ﴿هٰذَا مَا لَدَيَّ عَتِيدٌ﴾ [ق/٢٣] أي: هذا الذي أُمِرتُ بإحضاره قد أحضرته، فيقال عند إحضاره: ﴿أَلْقِيَا فِي جَهَنَّمَ كُلَّ كَفَّارٍ عَنِيدٍ﴾ [ق/٢٤]، كما يُحضِر الجاني إلى حضرة السلطان، فيقال: هذا فلان قد أُحضِر، فيقول: اذهبوا به إلى السجن وعاقبوه بما يستحقه!""",
